import ee, datetime, math
ee.Initialize(project='earthsense-436113')

# 1) Geometry & constants
geom_center = ee.Geometry.Point([30.40, 31.55])
geom = geom_center.buffer(8000).bounds()  # ~16x16 km coastal box
scale_m = 1000

def mask_landsat_l2(img):
    qa = img.select('QA_PIXEL')
    # Bits: 2 cirrus, 3 cloud, 4 cloud shadow, 5 snow
    mask = (qa.bitwiseAnd(1 << 2).eq(0)
            .And(qa.bitwiseAnd(1 << 3).eq(0))
            .And(qa.bitwiseAnd(1 << 4).eq(0))
            .And(qa.bitwiseAnd(1 << 5).eq(0)))
    return img.updateMask(mask)

def scale_sr(img):
    # Apply scale and offset to SR bands
    sr_bands = img.select([b for b in img.bandNames().getInfo() if b.startswith('SR_B')])
    scaled = sr_bands.multiply(2.75e-5).add(-0.2)
    # Keep QA_PIXEL for masking reference if needed
    return img.addBands(scaled, overwrite=True)

def compute_mndwi(img, sensor_code):
    # sensor_code: 'LT05','LT04','LE07' => green=SR_B2, swir1=SR_B5; 'LC08','LC09' => green=SR_B3, swir1=SR_B6
    if sensor_code in ['LT05','LT04','LE07']:
        g, s1 = 'SR_B2', 'SR_B5'
    else:
        g, s1 = 'SR_B3', 'SR_B6'
    green = img.select(g)
    swir1 = img.select(s1)
    mndwi = green.subtract(swir1).divide(green.add(swir1)).rename('mndwi')
    return mndwi

def fetch_best_image(coll_ids, date_str, geom):
    target = datetime.datetime.strptime(date_str, "%Y-%m-%d")
    for window in [30, 90]:
        start = (target - datetime.timedelta(days=window)).strftime("%Y-%m-%d")
        end = (target + datetime.timedelta(days=window)).strftime("%Y-%m-%d")
        for cid in coll_ids:
            col = (ee.ImageCollection(cid)
                   .filterBounds(geom)
                   .filterDate(start, end))
            try:
                size = col.size().getInfo()
            except Exception:
                return None, None, None, None
            if size and size > 0:
                img = col.sort('CLOUD_COVER').first()
                sensor_code = cid.split('/')[1][:4]  # e.g., 'LT05', 'LC08'
                return img, sensor_code, size, window
    return None, None, None, None

def water_stats(date_str, primary_ids, label):
    img, sensor, count, window = fetch_best_image(primary_ids, date_str, geom)
    if img is None:
        return {'status':'C1'}
    try:
        img = mask_landsat_l2(img)
        img = scale_sr(img)
        mndwi = compute_mndwi(img, sensor)
        # Counts
        total = ee.Image.constant(1).rename('one').reduceRegion(
            reducer=ee.Reducer.count(), geometry=geom, scale=scale_m, maxPixels=1e9).get('one').getInfo()
        valid = mndwi.reduceRegion(
            reducer=ee.Reducer.count(), geometry=geom, scale=scale_m, maxPixels=1e9).get('mndwi').getInfo()
        if valid is None or total is None:
            return {'status':'C3'}
        if int(valid) == 0:
            return {'status':'C2'}
        water_px = ee.Image(mndwi.gt(0)).rename('w').reduceRegion(
            reducer=ee.Reducer.sum(), geometry=geom, scale=scale_m, maxPixels=1e9).get('w').getInfo()
        if water_px is None:
            return {'status':'C3'}
        water_frac = float(water_px) / float(valid)
        if math.isnan(water_frac) or water_frac < 0 or water_frac > 1:
            return {'status':'C3'}
        cloud_pct = 100.0 * (1.0 - float(valid)/float(total))
        img_date = ee.Date(img.get('system:time_start')).format('YYYY-MM-dd').getInfo()
        return {
            'status':'OK','label':label,'sensor':sensor,'date':img_date,'win':window,'count':count,
            'valid':int(valid),'total':int(total),'cloud_pct':cloud_pct,'water_px':int(water_px),
            'water_frac':water_frac
        }
    except Exception:
        return {'status':'D'}

# 2) Compute stats for both dates
s1984 = water_stats('1984-07-25', ['LANDSAT/LT05/C02/T1_L2','LANDSAT/LT04/C02/T1_L2'], '1984')
s2021 = water_stats('2021-08-16', ['LANDSAT/LC08/C02/T1_L2','LANDSAT/LE07/C02/T1_L2'], '2021')

# 3) Handle failure cases
def bail(tag):
    print(tag)
    raise SystemExit()

if s1984.get('status') != 'OK' or s2021.get('status') != 'OK':
    tag_map = {'C1':'C1','C2':'C2','C3':'C3','D':'D'}
    first_fail = s1984.get('status') if s1984.get('status')!='OK' else s2021.get('status')
    bail(tag_map.get(first_fail, 'D'))

# 4) Print concise evidence
print(f"{s1984['label']}: {s1984['sensor']} {s1984['date']}, imgs:{s1984['count']}, win±{s1984['win']}d, "
      f"valid:{s1984['valid']}/{s1984['total']} (cloud~{s1984['cloud_pct']:.1f}%), "
      f"water_px:{s1984['water_px']}, water_frac:{s1984['water_frac']:.3f}")
print(f"{s2021['label']}: {s2021['sensor']} {s2021['date']}, imgs:{s2021['count']}, win±{s2021['win']}d, "
      f"valid:{s2021['valid']}/{s2021['total']} (cloud~{s2021['cloud_pct']:.1f}%), "
      f"water_px:{s2021['water_px']}, water_frac:{s2021['water_frac']:.3f}")

# 5) Decide retreat (increase in water fraction within the coastal strip)
diff = s2021['water_frac'] - s1984['water_frac']
print(f"Δ water_frac (2021-1984): {diff:.3f}")

# 6) Validate values and output final tag
if any([v is None for v in [diff]]) or math.isnan(diff):
    print("C3")
elif diff > 0.02:
    print("A")
else:
    print("B")
